import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Month 2021: Ceph Community Ambassador BoF","description":"","frontmatter":{"title":"Ceph Month 2021: Ceph Community Ambassador BoF","date":"2021-06-25T00:00:00.000Z","updated":"2021-06-25T00:00:00.000Z","tags":["Ceph社区","社区大使计划","分布式存储","Ceph活动组织","Ceph用户交流"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Ceph_Community_Ambassador_BoF.md","filePath":"posts/2021/Ceph_Month_2021_-_Ceph_Community_Ambassador_BoF.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Month_2021_-_Ceph_Community_Ambassador_BoF.md"};function r(h,a,p,s,n,_){return e(),i("div",null,[...a[0]||(a[0]=[t('<p>会议纪要</p><h3 id="会议主题-ceph社区大使计划讨论" tabindex="-1">会议主题：Ceph社区大使计划讨论 <a class="header-anchor" href="#会议主题-ceph社区大使计划讨论" aria-label="Permalink to &quot;会议主题：Ceph社区大使计划讨论&quot;">​</a></h3><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="参会人员-列出主要参会人员" tabindex="-1">参会人员：[列出主要参会人员] <a class="header-anchor" href="#参会人员-列出主要参会人员" aria-label="Permalink to &quot;参会人员：[列出主要参会人员]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>社区大使计划的提出</strong></p><ul><li>背景：由于社区管理员工作量大，特别是在疫情后活动恢复期间，提出建立社区大使计划以协助社区管理员。</li><li>目的：在各地组织活动时提供支持，协助社区管理员。</li></ul></li><li><p><strong>社区大使的职责</strong></p><ul><li>组织活动：协助或组织Ceph Day活动，包括预算申请、场地安排、餐饮和社交活动。</li><li>协调meetup：与各地meetup组织者合作，确保活动的活跃性和更新meetup wiki页面。</li><li>支持会议：协助本地会议的组织，包括提供swag和寻找演讲者。</li><li>内容协调：参与CFP协调，与市场开发工作组合作，更新网站内容。</li></ul></li><li><p><strong>具体行动计划</strong></p><ul><li>更新社区列表：创建或调整社区邮件列表，确保所有相关人员都能收到更新。</li><li>联系meetup组织者：根据地区分工，联系各地meetup组织者，了解活动状态并提供支持。</li><li>准备活动物资：为即将恢复的线下活动准备swag和其他物资。</li></ul></li><li><p><strong>后续行动</strong></p><ul><li>邮件列表更新：会议结束后，将更新社区邮件列表，并邀请参会人员加入。</li><li>活动准备：根据疫情和地区限制，准备即将到来的Ceph Day和其他社区活动。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>建立社区大使计划，明确大使的职责和行动计划。</li><li>更新和维护社区邮件列表，确保信息流通。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>更新社区邮件列表，并邀请相关人员加入。</li><li>根据地区分工，联系meetup组织者，了解活动状态并提供支持。</li><li>准备即将到来的Ceph Day和其他社区活动的物资和计划。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>感谢所有参会人员的参与和贡献，我们将继续在邮件列表中跟进相关事宜。</p><p>在原始字幕内容中，提到了以下关键信息：</p><ul><li>社区大使计划</li><li>Ceph Day活动</li><li>Meetup组织</li><li>CFP协调</li><li>内容更新</li><li>社区邮件列表</li><li>活动物资准备</li><li>地区分工</li><li>线下活动恢复</li><li>社区交流</li></ul><p>这些信息在改进后的总结中得到了准确反映。</p>',15)])])}const m=l(o,[["render",r]]);export{d as __pageData,m as default};
